export const FRAMES=[{id:'round',name:'Round & lovely',symbol:'◯'},{id:'square',name:'Smart squares',symbol:'▢'},{id:'cat-eye',name:'A little cat-eye',symbol:'◇'}];
export const UPGRADES=[{id:'plant',name:'A leafy friend',cost:60,description:'A little green, a lot of happy.',icon:'🌿'},{id:'chair',name:'The cozy corner',cost:100,description:'A soft pink seat for your patients.',icon:'🛋️'},{id:'equipment',name:'Brighter beginnings',cost:150,description:'New exam equipment. +10 coins per visit.',icon:'🔬'}];
const dirs=['up','right','down','left'];
export function createGame(p={}){return {coins:p.coins??100,completedVisits:p.completedVisits??0,upgrades:[...(p.upgrades??[])],visit:{stage:'idle'},feedback:''};}
export function startVisit(g,patient,directions,focusTarget){if(!['idle','complete'].includes(g.visit.stage))return g;if(!Array.isArray(directions)||directions.length!==3||!directions.every(d=>dirs.includes(d)))return g;return {...g,feedback:'',visit:{stage:'chart',patient,directions,round:0,focusTarget:Math.max(20,Math.min(80,focusTarget)),focusValue:0}};}
export function answerChart(g,direction){if(g.visit.stage!=='chart'||!dirs.includes(direction))return g;if(g.visit.directions[g.visit.round]!==direction)return {...g,feedback:'Almost! Look at the open side of the E. Try again.'};const round=g.visit.round+1;return {...g,feedback:round===3?'Lovely work! Let’s find a little clarity.':'You got it! Here comes the next one.',visit:{...g.visit,round,stage:round===3?'focus':'chart'}};}
export function setFocus(g,value){if(g.visit.stage!=='focus'||!Number.isFinite(value))return g;return {...g,feedback:'',visit:{...g.visit,focusValue:Math.max(0,Math.min(100,value))}};}
export function confirmFocus(g){if(g.visit.stage!=='focus')return g;if(Math.abs(g.visit.focusValue-g.visit.focusTarget)>8)return {...g,feedback:'Not quite clear yet. Move the slider a little and try again.'};return {...g,feedback:'Looking bright! Time to pick some frames.',visit:{...g.visit,stage:'frames'}};}
export function finishVisit(g,frame){if(g.visit.stage!=='frames'||!FRAMES.some(f=>f.id===frame))return g;const matched=frame===g.visit.patient.preference;const reward=40+(matched?10:0)+(g.upgrades.includes('equipment')?10:0);return {...g,coins:g.coins+reward,completedVisits:g.completedVisits+1,feedback:'',visit:{...g.visit,stage:'complete',frame,matched,reward}};}
export function buyUpgrade(g,id){const upgrade=UPGRADES.find(u=>u.id===id);if(!upgrade||g.upgrades.includes(id)||g.coins<upgrade.cost)return g;return {...g,coins:g.coins-upgrade.cost,upgrades:[...g.upgrades,id]};}
